import * as THREE from 'three/webgpu';
import { MeshBasicNodeMaterial, texture } from 'three/tsl';

export default function createNode(config, ctx) {
  const container = new THREE.Group();
  const resources = [];
  const timelines = [];

  // Safely get asset URL
  const imageUrl = config?.assets?.imageUrl;
  if (!imageUrl) {
    console.warn('No imageUrl provided in config.assets');
    container.userData.cleanup = () => {};
    container.userData.handlers = {};
    return container;
  }

  // Load texture (cached by ctx.textureLoader)
  const imageTexture = ctx.textureLoader.load(imageUrl);
  resources.push(imageTexture);

  // Plane dimensions based on atlas region aspect ratio: 512 x 320
  const planeAspect = 512 / 320;
  const planeGeo = new THREE.PlaneGeometry(planeAspect, 1.0);
  resources.push(planeGeo);

  // Create material with texture
  const planeMat = new MeshBasicNodeMaterial({
    colorNode: texture(imageTexture),
    side: THREE.DoubleSide
  });

  const planeMesh = new THREE.Mesh(planeGeo, planeMat);
  container.add(planeMesh);
  resources.push(planeMat);

  // Render text "Collection" (headline role, 0.34 scene units)
  if (config?.textContent && Array.isArray(config.textContent) && config.textContent.length > 0) {
    const textEntry = config.textContent[0];
    const textStr = typeof textEntry === 'string' ? textEntry : (textEntry?.text || textEntry || '');

    if (textStr && ctx.fontAtlas && typeof ctx.fontAtlas.renderText === 'function') {
      const textMesh = ctx.fontAtlas.renderText(textStr, {
        fontSize: 0.34,
        fontFamily: 'Lora',
        fontWeight: 400,
        color: config.colors?.paper || '#e8ecf2',
        align: 'center',
        anchor: 'center'
      });

      if (textMesh && textMesh instanceof THREE.Object3D) {
        textMesh.position.z = 0.01;
        container.add(textMesh);
        resources.push(textMesh);
      }
    }
  }

  // Apply scene transform
  if (config?.scenePosition) {
    const pos = config.scenePosition;
    container.position.set(pos.x ?? 0, pos.y ?? 3, pos.z ?? 0);
  } else {
    container.position.set(0, 3, 0);
  }

  if (config?.sceneRotation) {
    const rot = config.sceneRotation;
    container.rotation.order = 'XYZ';
    container.rotation.set(rot.x ?? 0, rot.y ?? 0, rot.z ?? 0);
  }

  if (config?.sceneScale) {
    const scl = config.sceneScale;
    container.scale.set(scl.x ?? 1, scl.y ?? 1, scl.z ?? 1);
  }

  // Apply cinematic primitives
  if (config?.cinematicPrimitives && Array.isArray(config.cinematicPrimitives)) {
    config.cinematicPrimitives.forEach(prim => {
      if (prim?.name && ctx.primitives && typeof ctx.primitives[prim.name] === 'function') {
        try {
          ctx.primitives[prim.name](container, prim.params || {});
        } catch (e) {
          console.warn(`Failed to apply primitive ${prim.name}:`, e);
        }
      }
    });
  }

  // Cleanup function
  container.userData.cleanup = () => {
    timelines.forEach(tl => {
      if (tl && typeof tl.kill === 'function') {
        tl.kill();
      }
    });

    resources.forEach(res => {
      if (res && typeof res.dispose === 'function') {
        res.dispose();
      }
    });
  };

  // Event handlers container
  container.userData.handlers = {};

  return container;
}
